#!/usr/bin/env python3
"""Compute hybrid score-ledger ground truth for CSX-195_Q1."""

from __future__ import annotations

import csv
import json
import re
from datetime import date
from html.parser import HTMLParser
from pathlib import Path
from typing import Any
from urllib.parse import parse_qs, unquote, urlparse


TASK_ID = "CSX-195_Q1"
EVENT_ID = "CSX-195"
TARGET_FAMILY = "upper_air_smoke_transport_score_ledger"
TASK_DIR = Path(__file__).resolve().parent
REPO_ROOT = TASK_DIR.parents[2]
PACKAGE_DIR = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID
OUT = TASK_DIR / "computed_gt.json"

SOURCE_FILES = [
    "metadata/event.json",
    "metadata/files.csv",
    "data/event_reports/event_reports_003_Locked_event_anchor_2019-2020_Australian_smoke_over_the_South_Pacific.json",
    "data/event_reports/event_reports_004_Locked_anchor_report_NASA_Earth_Observatory.html",
    "data/other/other_001_NASA_Earth_Observatory_Explosive_Fire_Activity_in_Australia.html",
    "data/physical_hazard/physical_hazard_009_Sentinel-2_SR_Harmonized_dNBR.json",
    "data/remote_sensing/remote_sensing_002_Google_Satellite_Embedding_annual_cosine-change_stats.json",
]


class TextExtractor(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self.parts: list[str] = []

    def handle_data(self, data: str) -> None:
        clean = data.strip()
        if clean:
            self.parts.append(clean)

    def text(self) -> str:
        return re.sub(r"\s+", " ", " ".join(self.parts)).strip()


def read_text(relative_path: str) -> str:
    return (PACKAGE_DIR / relative_path).read_text(encoding="utf-8-sig", errors="replace")


def load_json(relative_path: str) -> dict[str, Any]:
    return json.loads(read_text(relative_path))


def html_to_text(raw_html: str) -> str:
    parser = TextExtractor()
    parser.feed(raw_html)
    return parser.text()


def parse_day(raw: str) -> date:
    return date.fromisoformat(raw)


def inclusive_days(start_day: date, end_day: date) -> int:
    return (end_day - start_day).days + 1


def manifest_paths() -> set[str]:
    with (PACKAGE_DIR / "metadata" / "files.csv").open("r", encoding="utf-8-sig", newline="") as handle:
        return {row["relative_path"] for row in csv.DictReader(handle)}


def require_sources() -> None:
    paths = manifest_paths()
    missing = sorted(path for path in SOURCE_FILES if path.startswith("data/") and path not in paths)
    if missing:
        raise ValueError(f"Missing source files: {missing}")


def remote_image_dates() -> dict[str, str]:
    dates: dict[str, str] = {}
    with (PACKAGE_DIR / "metadata" / "files.csv").open("r", encoding="utf-8-sig", newline="") as handle:
        for row in csv.DictReader(handle):
            rel_path = row.get("relative_path", "")
            if rel_path not in {
                "data/remote_sensing/remote_sensing_004_pre.jpg",
                "data/remote_sensing/remote_sensing_005_event.jpg",
            }:
                continue
            query = parse_qs(urlparse(unquote(row.get("url", ""))).query)
            if query.get("TIME"):
                dates[rel_path] = query["TIME"][0]
    return dates


def extract_altitude(context_text: str) -> tuple[int, int]:
    match = re.search(r"between\s+(\d+)\s+to\s+(\d+)\s+kilometers", context_text, flags=re.I)
    if not match:
        raise ValueError("Smoke altitude range not found")
    return int(match.group(1)), int(match.group(2))


def transport_signals(anchor_text: str, context_text: str) -> dict[str, bool]:
    anchor = anchor_text.lower()
    context = context_text.lower()
    return {
        "jan4_image_context": "january 4, 2020" in anchor and "aqua" in anchor,
        "tan_smoke": "smoke has a tan color" in anchor,
        "pyrocumulonimbus": "pyrocumulonimbus" in anchor,
        "fire_cloud_dates": "december 29, 2019" in context and "january 4, 2020" in context,
        "pacific_new_zealand": "crossing the pacific" in context and "new zealand" in context,
        "snow_halfway_travel": "mountaintop snow" in context and "more than halfway around the earth" in context,
    }


def rounded(value: float, digits: int = 3) -> float:
    return round(float(value), digits)


def build_result() -> dict[str, Any]:
    require_sources()

    event = load_json("metadata/event.json")
    anchor = load_json(
        "data/event_reports/event_reports_003_Locked_event_anchor_2019-2020_Australian_smoke_over_the_South_Pacific.json"
    )
    anchor_text = html_to_text(read_text("data/event_reports/event_reports_004_Locked_anchor_report_NASA_Earth_Observatory.html"))
    context_text = html_to_text(read_text("data/other/other_001_NASA_Earth_Observatory_Explosive_Fire_Activity_in_Australia.html"))
    burn_index = load_json("data/physical_hazard/physical_hazard_009_Sentinel-2_SR_Harmonized_dNBR.json")
    annual_change = load_json("data/remote_sensing/remote_sensing_002_Google_Satellite_Embedding_annual_cosine-change_stats.json")

    start_day = parse_day(anchor["temporal_window"]["start_date"])
    end_day = parse_day(anchor["temporal_window"]["end_date"])
    event_days = inclusive_days(start_day, end_day)
    image_day = date(2020, 1, 4)
    height_day = date(2020, 1, 6)
    lag_days = (height_day - image_day).days

    altitude_min, altitude_max = extract_altitude(context_text)
    upper_air_threshold_km = 12
    altitude_margin_km = altitude_min - upper_air_threshold_km

    signals = transport_signals(anchor_text, context_text)
    transport_signal_count = sum(signals.values())

    image_dates = remote_image_dates()
    event_image_date = parse_day(image_dates["data/remote_sensing/remote_sensing_005_event.jpg"])
    dnbr_mean = rounded(burn_index["stats"]["sentinel2_dnbr_mean"])
    annual_mean = rounded(annual_change["stats"]["alphaearth_1_minus_cosine_mean"])

    transport_tests = {
        "duration_10_to_16_days": 10 <= event_days <= 16,
        "lag_no_more_than_2_days": lag_days <= 2,
        "altitude_margin_nonnegative": altitude_margin_km >= 0,
        "signal_count_at_least_5": transport_signal_count >= 5,
    }
    surface_tests = {
        "burn_index_mean_at_least_0_27": dnbr_mean >= 0.27,
        "annual_change_mean_at_least_0_05": annual_mean >= 0.05,
        "event_image_inside_window": start_day <= event_image_date <= end_day,
    }

    transport_score = sum(transport_tests.values())
    surface_score = sum(surface_tests.values())
    score_gap = transport_score - surface_score
    final_label = (
        "upper_air_smoke_transport_pass"
        if transport_score == 4 and score_gap >= 2
        else "mixed_signal_recheck"
    )

    primary_gt = {
        "event_days": event_days,
        "image_to_height_lag_days": lag_days,
        "altitude_margin_km": altitude_margin_km,
        "transport_signal_count": transport_signal_count,
        "transport_score": transport_score,
        "surface_score": surface_score,
        "score_gap": score_gap,
        "final_label": final_label,
    }

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "short_answer",
        "target_family": TARGET_FAMILY,
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": primary_gt,
        "numeric_tolerances": {
            "event_days": {"target": event_days, "absolute_tolerance": 0},
            "image_to_height_lag_days": {"target": lag_days, "absolute_tolerance": 0},
            "altitude_margin_km": {"target": altitude_margin_km, "absolute_tolerance": 0},
            "transport_signal_count": {"target": transport_signal_count, "absolute_tolerance": 0},
            "transport_score": {"target": transport_score, "absolute_tolerance": 0},
            "surface_score": {"target": surface_score, "absolute_tolerance": 0},
            "score_gap": {"target": score_gap, "absolute_tolerance": 0},
        },
        "key_values": {
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "event_window": f"{start_day.isoformat()} to {end_day.isoformat()}",
            "image_date": image_day.isoformat(),
            "height_date": height_day.isoformat(),
            "smoke_altitude_km_range": [altitude_min, altitude_max],
            "upper_air_threshold_km": upper_air_threshold_km,
            "transport_signals": signals,
            "transport_tests": transport_tests,
            "surface_tests": surface_tests,
            "mean_burn_index_proxy": dnbr_mean,
            "mean_annual_feature_change_proxy": annual_mean,
            "remote_image_dates": image_dates,
            "classification_rule": "transport_score == 4 and score_gap >= 2",
            "surface_proxy_scope": (
                "Surface proxy layers are used only as a comparison score against the upper-air transport ledger; "
                "they are not treated as proof of an event burn perimeter."
            ),
        },
        "formulas": {
            "event_days": "inclusive_days(event_start, event_end)",
            "image_to_height_lag_days": "height_anchor_date - image_anchor_date",
            "altitude_margin_km": "minimum_reported_smoke_height_km - 12",
            "score_gap": "transport_score - surface_score",
        },
        "rubric": {
            "total_points": 20,
            "criteria": [
                {
                    "name": "Ledger structure",
                    "points": 3,
                    "description": "Returns exactly the requested eight-key compact JSON ledger with integer counts and the final label.",
                    "partial_credit": "Award 1-2 points for a mostly correct structure with one or two missing or renamed fields; no credit for prose-only output.",
                },
                {
                    "name": "Window and lag arithmetic",
                    "points": 4,
                    "description": "Computes 13 inclusive event days and a 2-day image-to-height lag.",
                    "partial_credit": "Award 2 points for one correct value; award 1 point for traceable exclusive-date arithmetic.",
                },
                {
                    "name": "Altitude threshold test",
                    "points": 3,
                    "description": "Uses the 15-19 km smoke range, the 12 km threshold, and the 3 km minimum-height margin.",
                    "partial_credit": "Award 1-2 points for using the right range but the wrong margin or threshold comparison.",
                },
                {
                    "name": "Transport signal count",
                    "points": 3,
                    "description": "Counts all six specified report signals and applies the at-least-5 pass rule.",
                    "partial_credit": "Award 1-2 points for recognizing most signals but missing a paired wording test.",
                },
                {
                    "name": "Transport score",
                    "points": 3,
                    "description": "Computes transport_score = 4 from the duration, lag, altitude, and signal-count tests.",
                    "partial_credit": "Award 1-2 points for correct component tests with an arithmetic or threshold error.",
                },
                {
                    "name": "Surface comparison score",
                    "points": 2,
                    "description": "Computes surface_score = 1 from two failed surface proxy thresholds and the event-image date pass, while treating surface proxies as comparison evidence rather than burn-perimeter proof.",
                    "partial_credit": "Award 1 point for using the right proxy values but the wrong threshold outcome.",
                },
                {
                    "name": "Gap and label",
                    "points": 2,
                    "description": "Computes score_gap = 3 and assigns upper_air_smoke_transport_pass.",
                    "partial_credit": "Award 1 point for the right label with a wrong gap, or the right gap with an incorrect label.",
                },
            ],
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
        },
    }


def main() -> None:
    result = build_result()
    OUT.write_text(json.dumps(result, ensure_ascii=True, indent=2, sort_keys=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
